using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow tests ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(25.00, 2, 0.10, 55.00, DisplayName = "Two items, 10% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price, any quantity")]
    [DataRow(99.99, 0, 0.05, 0.00, DisplayName = "Zero quantity returns zero")]
    [DataRow(100.00, 1, 1.0, 200.00, DisplayName = "Maximum tax rate (100%)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // --- CalculateTotal: DynamicData from method ---

    [TestMethod]
    [DynamicData(nameof(GetCalculateTotalEdgeCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_EdgeCases_ReturnsExpectedTotal(
        decimal unitPrice, int quantity, decimal taxRate, decimal expectedTotal)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expectedTotal, result);
    }

    private static IEnumerable<object[]> GetCalculateTotalEdgeCases()
    {
        yield return [0.01m, 1, 0.0m, 0.01m];        // Smallest meaningful price
        yield return [9999.99m, 100, 0.25m, 1249998.75m]; // Large order with tax
        yield return [1.00m, 1, 0.07m, 1.07m];       // Common US sales tax
        yield return [19.99m, 3, 0.20m, 71.964m];    // UK VAT scenario
    }

    // --- CalculateTotal: Invalid inputs ---

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price throws")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // --- ApplyDiscount: DataRow tests ---

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% discount")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% discount (free)")]
    [DataRow(49.99, 25.0, 37.4925, DisplayName = "Fractional result")]
    [DataRow(0.00, 50.0, 0.00, DisplayName = "Zero price with discount")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        double price, double discountPercent, double expectedPrice)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expectedPrice, result);
    }

    // --- ApplyDiscount: DynamicData from property ---

    [TestMethod]
    [DynamicData(nameof(DiscountBoundaryData), DynamicDataSourceType.Property)]
    public void ApplyDiscount_BoundaryCases_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expectedPrice)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expectedPrice, result);
    }

    public static IEnumerable<object[]> DiscountBoundaryData =>
    [
        [200.00m, 0.01m, 199.98m],   // Smallest possible discount
        [200.00m, 99.99m, 0.02m],    // Near-maximum discount
        [1000.00m, 33.33m, 666.70m], // Repeating decimal percentage
    ];

    // --- ApplyDiscount: Invalid inputs ---

    [TestMethod]
    [DataRow(100.00, -1.0, DisplayName = "Negative discount throws")]
    [DataRow(100.00, 100.01, DisplayName = "Discount above 100% throws")]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRangeException(
        double price, double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
    }
}

